module.exports = async function(data) {
  const rawUser = data.read_user;
  const user = Array.isArray(rawUser) ? rawUser[0] : rawUser;
  const email = user && typeof user.email === 'string' ? user.email.trim() : '';
  const body = (data.$trigger && data.$trigger.body) || {};

  const subscriptionId = typeof body.subscriptionId === 'string' ? body.subscriptionId.trim() : '';
  const subscriptionItemId = typeof body.subscriptionItemId === 'string' ? body.subscriptionItemId.trim() : '';
  const currentPriceId = typeof body.currentPriceId === 'string' ? body.currentPriceId.trim() : '';
  const newPriceId = typeof (body.newPriceId || body.targetPriceId) === 'string'
    ? String(body.newPriceId || body.targetPriceId).trim()
    : '';
  const expectedPeriodEnd = typeof body.currentPeriodEnd === 'number' && Number.isFinite(body.currentPeriodEnd)
    ? Math.trunc(body.currentPeriodEnd)
    : null;

  const isValidSubId = /^sub_[A-Za-z0-9_]+$/.test(subscriptionId);
  const isValidItemId = /^si_[A-Za-z0-9_]+$/.test(subscriptionItemId);
  const isValidCurrentPrice = /^price_[A-Za-z0-9_]+$/.test(currentPriceId);
  const isValidNewPrice = /^price_[A-Za-z0-9_]+$/.test(newPriceId);

  if (!email) {
    return {
      valid: false,
      errorCode: 'UNAUTHORIZED',
      message: 'Authentication is required to preview a subscription plan change.',
    };
  }

  if (!isValidSubId || !isValidItemId || !isValidCurrentPrice || !isValidNewPrice || currentPriceId === newPriceId) {
    return {
      valid: false,
      errorCode: 'INVALID_PREVIEW_PARAMETERS',
      message: 'Valid subscription, subscription item, current price, and target price identifiers are required.',
    };
  }

  return {
    valid: true,
    email,
    encodedEmail: encodeURIComponent(email),
    subscriptionId,
    subscriptionItemId,
    currentPriceId,
    newPriceId,
    expectedPeriodEnd,
  };
};

module.exports = async function(data) {
  const status = data.get_customer && data.get_customer.status;
  const body = data.get_customer && data.get_customer.data;
  if ((typeof status === 'number' && status >= 400) || !body || body.error || !Array.isArray(body.data)) {
    return { customerId: null, lookupError: true };
  }
  const customer = body.data.length > 0 ? body.data[0] : null;
  return {
    customerId: customer ? customer.id : null,
    lookupError: false,
  };
};

module.exports = async function(data) {
  const req = data.validate_request || {};
  const customerId = data.extract_customer && data.extract_customer.customerId;
  const subsData = data.get_subscriptions && data.get_subscriptions.data;
  const pricesData = data.get_prices && data.get_prices.data;

  if (!customerId || !subsData || !Array.isArray(subsData.data) || !pricesData || !Array.isArray(pricesData.data)) {
    return {
      allowed: false,
      errorCode: 'UPGRADE_PREVIEW_UNAVAILABLE',
      message: 'Could not verify subscription or pricing records with Stripe.',
    };
  }

  const activeSub = subsData.data.find(function(s) {
    return s.id === req.subscriptionId && ['active', 'trialing'].includes(s.status);
  }) || null;

  if (!activeSub || activeSub.customer !== customerId) {
    return {
      allowed: false,
      errorCode: 'SUBSCRIPTION_OWNERSHIP_MISMATCH',
      message: 'The requested subscription does not belong to the authenticated account or is not active.',
    };
  }

  const items = (activeSub.items && Array.isArray(activeSub.items.data)) ? activeSub.items.data : [];
  const currentItem = items.find(function(item) { return item.id === req.subscriptionItemId; }) || items[0] || null;
  if (!currentItem || currentItem.id !== req.subscriptionItemId) {
    return {
      allowed: false,
      errorCode: 'SUBSCRIPTION_ITEM_MISMATCH',
      message: 'The subscription item has changed. Please refresh billing and try again.',
    };
  }

  const actualCurrentPriceId = currentItem.price && currentItem.price.id;
  if (!actualCurrentPriceId || actualCurrentPriceId !== req.currentPriceId) {
    return {
      allowed: false,
      errorCode: 'CONCURRENT_SUBSCRIPTION_CHANGE',
      message: 'Your current subscription plan has changed since you opened this review. Please refresh billing.',
    };
  }

  if (req.expectedPeriodEnd && activeSub.current_period_end !== req.expectedPeriodEnd) {
    return {
      allowed: false,
      errorCode: 'PREVIEW_STALE_PERIOD_CHANGED',
      message: 'Your subscription billing period has updated. Please refresh billing to preview the current cycle.',
    };
  }

  const targetPrice = pricesData.data.find(function(p) {
    const productActive = !p.product || typeof p.product !== 'object' || p.product.active !== false;
    return p.id === req.newPriceId && p.active === true && p.type === 'recurring' && productActive;
  }) || null;

  if (!targetPrice || typeof targetPrice.unit_amount !== 'number') {
    return {
      allowed: false,
      errorCode: 'UNSUPPORTED_TARGET_PRICE',
      message: 'The selected subscription plan price is not an active recurring plan.',
    };
  }

  const currentAmount = typeof (currentItem.price && currentItem.price.unit_amount) === 'number'
    ? currentItem.price.unit_amount
    : 0;
  const currentCurrency = String((currentItem.price && currentItem.price.currency) || 'usd').toLowerCase();
  const targetCurrency = String(targetPrice.currency || 'usd').toLowerCase();

  if (targetCurrency !== currentCurrency) {
    return {
      allowed: false,
      errorCode: 'CURRENCY_MISMATCH',
      message: 'Target plan currency does not match the active subscription currency.',
    };
  }

  if (targetPrice.unit_amount <= currentAmount) {
    return {
      allowed: false,
      errorCode: 'NOT_AN_UPGRADE',
      message: 'Invoice proration preview is only applicable to subscription upgrades.',
    };
  }

  const prorationTimestamp = Math.floor(Date.now() / 1000);
  const formBody = [
    'customer=' + encodeURIComponent(customerId),
    'subscription=' + encodeURIComponent(activeSub.id),
    'subscription_details[items][0][id]=' + encodeURIComponent(currentItem.id),
    'subscription_details[items][0][price]=' + encodeURIComponent(targetPrice.id),
    'subscription_details[proration_behavior]=always_invoice',
    'subscription_details[proration_date]=' + encodeURIComponent(String(prorationTimestamp)),
  ].join('&');

  return {
    allowed: true,
    customerId,
    subscriptionId: activeSub.id,
    subscriptionItemId: currentItem.id,
    currentPriceId: actualCurrentPriceId,
    targetPriceId: targetPrice.id,
    targetUnitAmount: targetPrice.unit_amount,
    targetCurrency,
    targetInterval: (targetPrice.recurring && targetPrice.recurring.interval) || 'month',
    currentPeriodStart: activeSub.current_period_start,
    currentPeriodEnd: activeSub.current_period_end,
    prorationTimestamp,
    formBody,
  };
};

module.exports = async function(data) {
  const vReq = data.validate_request || {};
  const vOwn = data.verify_ownership_and_build_preview_body || {};
  const cust = data.extract_customer || {};

  let errorCode = vOwn.errorCode || vReq.errorCode || 'UPGRADE_PREVIEW_UNAVAILABLE';
  let message = vOwn.message || vReq.message || 'Unable to preview the subscription plan change right now.';

  if (vReq.valid && !cust.customerId && !vOwn.errorCode) {
    errorCode = cust.lookupError ? 'UPGRADE_PREVIEW_UNAVAILABLE' : 'SUBSCRIPTION_OWNERSHIP_MISMATCH';
    message = 'No active subscription was found for the authenticated account.';
  }

  return {
    verified: false,
    error: true,
    errorCode,
    code: errorCode,
    message,
  };
};

module.exports = async function(data) {
  const prep = data.verify_ownership_and_build_preview_body || {};
  const status = data.create_invoice_preview && data.create_invoice_preview.status;
  const inv = data.create_invoice_preview && data.create_invoice_preview.data;

  if ((typeof status === 'number' && status >= 400) || !inv || inv.error || typeof inv.amount_due !== 'number') {
    return {
      verified: false,
      error: true,
      errorCode: 'STRIPE_INVOICE_PREVIEW_FAILED',
      code: 'STRIPE_INVOICE_PREVIEW_FAILED',
      message: 'Could not retrieve the prorated invoice preview from Stripe.',
    };
  }

  const lines = (inv.lines && Array.isArray(inv.lines.data)) ? inv.lines.data : [];
  let prorationDelta = 0;
  let hasProrationLines = false;
  for (const line of lines) {
    const isProration = Boolean(
      line.proration === true ||
      (line.parent && line.parent.subscription_item_details && line.parent.subscription_item_details.proration === true) ||
      (line.parent && line.parent.invoice_item_details && line.parent.invoice_item_details.proration === true)
    );
    if (isProration && typeof line.amount === 'number') {
      prorationDelta += line.amount;
      hasProrationLines = true;
    }
  }

  const subtotal = typeof inv.subtotal === 'number' ? inv.subtotal : inv.amount_due;
  if (!hasProrationLines) {
    prorationDelta = subtotal;
  }

  const totalDiscountAmounts = Array.isArray(inv.total_discount_amounts) ? inv.total_discount_amounts : [];
  const discountAmount = totalDiscountAmounts.reduce(function(sum, d) {
    return sum + (typeof d.amount === 'number' ? d.amount : 0);
  }, 0);

  const totalTaxes = Array.isArray(inv.total_taxes) ? inv.total_taxes : [];
  const taxFromArray = totalTaxes.reduce(function(sum, t) {
    return sum + (typeof t.amount === 'number' ? t.amount : 0);
  }, 0);
  const tax = typeof inv.tax === 'number' ? inv.tax : taxFromArray;

  const amountDueToday = inv.amount_due;
  const currency = String(inv.currency || prep.targetCurrency || 'usd').toLowerCase();
  const previewTimestamp = prep.prorationTimestamp || Math.floor(Date.now() / 1000);
  const expiresAt = (previewTimestamp + 300) * 1000;

  return {
    verified: true,
    customerId: prep.customerId,
    subscriptionId: prep.subscriptionId,
    subscriptionItemId: prep.subscriptionItemId,
    currentPriceId: prep.currentPriceId,
    targetPriceId: prep.targetPriceId,
    newPriceId: prep.targetPriceId,
    currency,
    subtotal,
    prorationDelta,
    discountAmount,
    tax,
    amountDueToday,
    totalAmountDue: amountDueToday,
    renewalAmount: prep.targetUnitAmount,
    renewalInterval: prep.targetInterval || 'month',
    previewTimestamp,
    effectiveDate: previewTimestamp,
    currentPeriodStart: prep.currentPeriodStart,
    currentPeriodEnd: prep.currentPeriodEnd,
    nextBillingDate: prep.currentPeriodEnd,
    expiresAt,
    promoSupported: false,
    chargeAmountEnforcedByServer: false,
  };
};
